	}
	if got.NormalizedLoad != 1 {
		t.Fatalf("desk-a normalized_load=%v, want 1", got.NormalizedLoad)
	}
}

package routehealth

import (
	"sort"
	"strings"
	"sync"

	"github.com/DocumentDrivenDX/fizeau/internal/provider/utilization"
)

// UtilizationKey identifies one provider endpoint/model utilization sample.
type UtilizationKey struct {
	Provider string
	Endpoint string
	Model    string
}

// EndpointLoad is the normalized load signal used by routing.
type EndpointLoad struct {
	LeaseCount           int
	NormalizedLoad       float64
	UtilizationFresh     bool
	UtilizationSaturated bool
}

// UtilizationStore retains the most recent utilization sample for each
// provider endpoint. It is safe for concurrent use.
type UtilizationStore struct {
	mu      sync.RWMutex
	samples map[UtilizationKey]utilization.EndpointUtilization
}

// NewUtilizationStore returns an empty utilization store.
func NewUtilizationStore() *UtilizationStore {
	return &UtilizationStore{
		samples: make(map[UtilizationKey]utilization.EndpointUtilization),
	}
}

// NormalizeUtilizationKey trims whitespace from the utilization dimensions.
func NormalizeUtilizationKey(provider, endpoint, model string) UtilizationKey {
	return UtilizationKey{
		Provider: strings.TrimSpace(provider),
		Endpoint: strings.TrimSpace(endpoint),
		Model:    strings.TrimSpace(model),
	}
}

// Record stores the latest utilization sample for key.
func (s *UtilizationStore) Record(provider, endpoint, model string, sample utilization.EndpointUtilization) {
	if s == nil {
		return
	}
	key := NormalizeUtilizationKey(provider, endpoint, model)
	if key.Provider == "" && key.Endpoint == "" && key.Model == "" {
		return
	}
	if sample.Freshness == "" {
		sample.Freshness = utilization.FreshnessFresh
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.samples == nil {
		s.samples = make(map[UtilizationKey]utilization.EndpointUtilization)
	}
	s.samples[key] = cloneUtilization(sample)
}

// Sample returns the most recent utilization sample for provider/endpoint/model.
// When the endpoint-specific sample is unavailable, provider-wide samples are
// considered as a fallback so callers can still surface coarse utilization
// evidence without guessing at private probe internals.
func (s *UtilizationStore) Sample(provider, endpoint, model string) (utilization.EndpointUtilization, bool) {
	if s == nil {
		return utilization.EndpointUtilization{}, false
	}
	keyProvider := strings.TrimSpace(provider)
	keyEndpoint := strings.TrimSpace(endpoint)
	keyModel := strings.TrimSpace(model)

	s.mu.RLock()
	defer s.mu.RUnlock()
	if len(s.samples) == 0 {
		return utilization.EndpointUtilization{}, false
	}
	if sample, ok := s.samples[NormalizeUtilizationKey(keyProvider, keyEndpoint, keyModel)]; ok {
		return cloneUtilization(sample), true
	}
	if keyProvider != "" {
		if sample, ok := s.samples[NormalizeUtilizationKey(keyProvider, "", keyModel)]; ok {
			return cloneUtilization(sample), true
		}
	}
	return utilization.EndpointUtilization{}, false
}

// EndpointLoads returns the normalized load per endpoint for provider/model.
// Fresh utilization samples are combined with the supplied lease counts;
// stale or missing samples fall back to lease counts only.
func (s *UtilizationStore) EndpointLoads(provider, model string, leaseCounts map[string]int) map[string]EndpointLoad {
	if s == nil {
		return nil
	}
	keyProvider := strings.TrimSpace(provider)
	keyModel := strings.TrimSpace(model)

	s.mu.RLock()
	defer s.mu.RUnlock()
	if len(s.samples) == 0 && len(leaseCounts) == 0 {
		return nil
	}

	keys := make(map[string]struct{})
	for endpoint := range leaseCounts {
		keys[endpoint] = struct{}{}
	}
	for key := range s.samples {
		if keyProvider != "" && key.Provider != keyProvider {
			continue
		}
		if keyModel != "" && key.Model != keyModel {
			continue
		}
		if key.Endpoint != "" {
			keys[key.Endpoint] = struct{}{}
		}
	}
	if len(keys) == 0 {
		return nil
	}

	out := make(map[string]EndpointLoad, len(keys))
	for endpoint := range keys {
		leaseCount := leaseCounts[endpoint]
		load := EndpointLoad{
			LeaseCount:       leaseCount,
			NormalizedLoad:   float64(leaseCount),
			UtilizationFresh: false,
		}
		key := NormalizeUtilizationKey(keyProvider, endpoint, keyModel)
		sample, ok := s.samples[key]
		if !ok && keyProvider != "" {
			// Allow provider-wide samples to match when the caller does not
			// have a fully-qualified endpoint name.
			sample, ok = s.samples[NormalizeUtilizationKey(keyProvider, "", keyModel)]
		}
		if !ok || sample.Freshness != utilization.FreshnessFresh {
			out[endpoint] = load
			continue
		}
		normalized, saturated := normalizedLoadFromSample(sample)
		load.NormalizedLoad = float64(leaseCount) + normalized
		load.UtilizationFresh = true
		load.UtilizationSaturated = saturated
		out[endpoint] = load
	}

	return out
}

func normalizedLoadFromSample(sample utilization.EndpointUtilization) (float64, bool) {
	var active int
	var queued int
	if sample.ActiveRequests != nil {
		active = *sample.ActiveRequests
	}
	if sample.QueuedRequests != nil {
		queued = *sample.QueuedRequests
	}
	if sample.MaxConcurrency != nil && *sample.MaxConcurrency > 0 {
		total := active + queued
		pressure := float64(total) / float64(*sample.MaxConcurrency)
		if pressure < 0 {
			pressure = 0
		}
		return pressure, total >= *sample.MaxConcurrency
	}
	if sample.CacheUsage != nil {
		pressure := *sample.CacheUsage
		if pressure < 0 {
			pressure = 0
		}
		return pressure, pressure >= 1
	}
	total := active + queued
	if total < 0 {
		total = 0
	}
	return float64(total), false
}

func cloneUtilization(sample utilization.EndpointUtilization) utilization.EndpointUtilization {
	out := sample
	if sample.ActiveRequests != nil {
		out.ActiveRequests = utilization.Int(*sample.ActiveRequests)
	}
	if sample.QueuedRequests != nil {
		out.QueuedRequests = utilization.Int(*sample.QueuedRequests)
	}
	if sample.CacheUsage != nil {
		out.CacheUsage = utilization.Float64(*sample.CacheUsage)
	}
	if sample.MaxConcurrency != nil {
		out.MaxConcurrency = utilization.Int(*sample.MaxConcurrency)
	}
	return out
}

// EndpointLoadList returns a deterministic endpoint ordering for tests.
func EndpointLoadList(loads map[string]EndpointLoad) []string {
	if len(loads) == 0 {
		return nil
	}
	out := make([]string, 0, len(loads))
	for endpoint := range loads {
		out = append(out, endpoint)
	}
	sort.Strings(out)
	return out
}

// Package registry is the single source of truth for provider-type →
// factory mappings.
//
// Why this package exists. Before it, the agent had two parallel
// factories that knew about provider types: internal/config/config.go
// `BuildProvider` (config-time) and service_native_provider.go
// `buildNativeProvider` (service-execute time). When lucebox + vllm
// were added in v0.9.18-.20, only the first factory got the new types;
// the second one rejected requests pinning those providers at execute
// time. Two factories drifting is the architectural smell `agent-8e4eb44c`
// was filed to fix.
//
// Each provider package registers a Descriptor in its init(). Both
// factories call Lookup. New providers are one Register call away from
// being usable through every code path.
//
// The registry deliberately covers only the factory drift case in v1.
// Other type-switch sites (default port, base URL, surface map,
// capability flags, validators) are local to internal/config and
// don't have the cross-package drift problem; they stay there. Future
// drift cases can be additively folded into the registry as they appear.
package registry

import (
	"sort"
	"sync"

	agentcore "github.com/DocumentDrivenDX/fizeau/internal/core"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/quotaheaders"
	"github.com/DocumentDrivenDX/fizeau/internal/reasoning"
)

// Inputs is the canonical factory input shape. Both the config-time
// path (internal/config builds this from a ProviderConfig) and the
// service-time path (service_native_provider builds this from a
// ServiceProviderEntry) populate it. Provider factories take exactly
// one argument so the call sites can't accidentally diverge.
type Inputs struct {
	// ProviderName is the user-facing config name for this provider
	// (e.g., "vidar-omlx"). Distinct from the provider TYPE (e.g.,
	// "omlx"). Some factories include it in attribution metadata.
	ProviderName string

	// BaseURL is the resolved endpoint (with default substituted).
	BaseURL string
	// APIKey is the bearer token; empty for unauthenticated endpoints.
	APIKey string
	// Model is the configured default; empty when discovery is in use.
	Model string

	// ModelPattern is an optional regex used by openai-compat providers
	// during model discovery (Tier-2 ranking).
	ModelPattern string

	// KnownModels maps surface model IDs to canonical IDs from the
	// model catalog. Used by openai-compat providers to recognize
	// catalog-tracked models on a discovery list.
	KnownModels map[string]string

	// Headers is extra HTTP headers (OpenRouter, Azure, custom).
	Headers map[string]string

	// Reasoning is the per-provider default reasoning policy.
	Reasoning reasoning.Reasoning

	// ModelReasoningWire is a model_id → reasoning_wire map sourced
	// from the catalog. Today only openrouter and openai-compat
	// providers consume it; others ignore it.
	ModelReasoningWire map[string]string

	// QuotaSignalObserver, when set, is forwarded to provider factories
	// that support per-response rate-limit-header parsing (anthropic,
	// openai, openrouter). The service layer wires this to the provider
	// quota state machine so dispatch can route around providers whose
	// subscription/daily cap is hit. Providers that do not parse rate-limit
	// headers ignore this field.
	QuotaSignalObserver func(quotaheaders.Signal)
}

// Factory builds a provider from canonical inputs.
type Factory func(Inputs) agentcore.Provider

// Descriptor pairs a provider type with its factory + a small set of
// invariants. Provider packages register these in init().
type Descriptor struct {
	// Type is the canonical provider-type string (e.g., "omlx").
	// Matches the `type:` value in user config and the descriptor's
	// case in internal/config switches.
	Type string

	// Factory builds an agent.Provider from canonical inputs.
	Factory Factory

	// DefaultBaseURL is used by the config-normalizer when no base_url
	// is explicitly set.
	DefaultBaseURL string

	// DefaultPort is used by endpoint-config inference when only a
	// host is supplied. 0 means "no inference; require explicit BaseURL".
	DefaultPort int
}

var (
	mu      sync.RWMutex
	entries = map[string]Descriptor{}
)

// Register installs a provider Descriptor. Called from each provider
// package's init() function. Re-registering the same type panics —
// duplicate registration is always a programmer error.
func Register(d Descriptor) {
	if d.Type == "" {
		panic("provider/registry: Descriptor.Type is required")
	}
	if d.Factory == nil {
		panic("provider/registry: Descriptor.Factory is required for type " + d.Type)
	}
	mu.Lock()
	defer mu.Unlock()
	if _, exists := entries[d.Type]; exists {
		panic("provider/registry: duplicate registration for type " + d.Type)
	}
	entries[d.Type] = d
}

// Lookup returns the Descriptor for a provider type, or false if the
// type is not registered.
func Lookup(typ string) (Descriptor, bool) {
	mu.RLock()
	defer mu.RUnlock()
	d, ok := entries[typ]
	return d, ok
}

// Types returns all registered provider type names in sorted order.
// Used by validators and conformance descriptors that iterate over
// every known provider type.
func Types() []string {
	mu.RLock()
	defer mu.RUnlock()
	out := make([]string, 0, len(entries))
	for t := range entries {
		out = append(out, t)
	}
	sort.Strings(out)
	return out
}

